            </div>
            <div
              class="text-caption font-weight-bold grey--text text--darken-2 mt-3 mb-1"
            >
              DURATION
            </div>
            <div class="text-body-1 font-weight-medium">
              {{ formatDate(formData.startDate) }} -
              {{ formatDate(formData.endDate) }} ({{ calculatedDays }} days)
