              Confirm
            </v-btn>
          </v-card-actions>
        </v-card>
      </v-dialog>
      <v-row>
        <!-- Left Column: Balance Overview -->
        <v-col cols="12" lg="5">
          <div class="sticky-sidebar">
            <v-card outlined class="elevation-3">
              <v-card-title class="indigo darken-1 white--text py-3">
                <v-icon left color="white">mdi-chart-donut</v-icon>
                Maternity Leave Balance
                <v-spacer></v-spacer>
                <v-chip
                  color="white"
                  text-color="indigo darken-1"
                  small
                  class="font-weight-bold"
                >
                  {{ leaveType.details.period }}
                </v-chip>
              </v-card-title>
              <v-card-text class="pa-4">
                <div class="text-center mb-4">
                  <v-avatar color="indigo lighten-5" size="80" class="mb-2">
                    <span
                      class="text-h4 font-weight-bold indigo--text text--darken-2"
                    >
                      {{ leaveType.details.balance }}
                    </span>
                  </v-avatar>
                  <div
                    class="text-subtitle-1 font-weight-medium grey--text text--darken-1"
                  >
                    Days Available
                  </div>
                </div>

                <!-- Statistics Cards -->
                <v-row dense>
                  <v-col cols="6">
                    <v-card outlined class="pa-3 text-center blue lighten-5">
                      <div class="caption grey--text text--darken-2 mb-1">
                        MAX DAYS
                      </div>
                      <div
                        class="text-h5 font-weight-bold blue--text text--darken-2"
                      >
                        {{ leaveType.details.maxDays }}
                      </div>
                    </v-card>
                  </v-col>
                  <v-col cols="6">
                    <v-card outlined class="pa-3 text-center orange lighten-5">
                      <div class="caption grey--text text--darken-2 mb-1">
                        ACCRUED
                      </div>
                      <div
                        class="text-h5 font-weight-bold orange--text text--darken-2"
                      >
                        {{ leaveType.details.accrued }}
                      </div>
                    </v-card>
                  </v-col>
                  <v-col cols="6">
                    <v-card outlined class="pa-3 text-center green lighten-5">
                      <div class="caption grey--text text--darken-2 mb-1">
                        TAKEN
                      </div>
                      <div
                        class="text-h5 font-weight-bold green--text text--darken-2"
                      >
                        {{ leaveType.details.daysOnLeave }}
                      </div>
                    </v-card>
                  </v-col>
                  <v-col cols="6">
                    <v-card outlined class="pa-3 text-center purple lighten-5">
                      <div class="caption grey--text text--darken-2 mb-1">
                        REMAINING
                      </div>
                      <div
                        class="text-h5 font-weight-bold purple--text text--darken-2"
                      >
                        N/A
                      </div>
                    </v-card>
                  </v-col>
                </v-row>

                <!-- Leave Policy Info -->
                <v-alert type="info" dense text class="mt-4 mb-0" border="left">
                  <div class="caption">
                    <v-icon x-small color="info" class="mr-1"
                      >mdi-information</v-icon
                    >
                    <strong>Policy:</strong> Maternity leave includes weekends
                    and public holidays.
                  </div>
                </v-alert>
              </v-card-text>
            </v-card>
          </div>
        </v-col>

        <!-- Right Column: Form -->
        <v-col cols="12" lg="7">
          <!-- Step 1: Leave Request Form -->
          <v-card outlined class="mb-4">
            <v-card-title class="subtitle-1 font-weight-bold py-2 px-4">
              <v-icon small class="mr-2">mdi-numeric-1-circle</v-icon>
              Leave Request Details
            </v-card-title>
            <v-card-text class="pa-4">
              <v-form ref="form" v-model="valid">
                <v-row>
                  <!-- Start Date -->
                  <v-col cols="12" md="6">
                    <v-menu
                      v-model="startDateMenu"
                      :close-on-content-click="false"
                      transition="scale-transition"
                      offset-y
                      min-width="290px"
                    >
                      <template v-slot:activator="{ on, attrs }">
                        <v-text-field
                          v-model="formData.startDate"
                          label="Start Date *"
                          prepend-icon="mdi-calendar-start"
                          readonly
                          outlined
                          :rules="[rules.required]"
                          v-bind="attrs"
                          v-on="on"
                          :error-messages="dateErrorMessages"
                        ></v-text-field>
                      </template>
                      <v-date-picker
                        v-model="formData.startDate"
                        :min="minStartDate"
                        @input="onStartDateSelected"
                      ></v-date-picker>
                    </v-menu>
                  </v-col>

                  <!-- End Date -->
                  <v-col cols="12" md="6">
                    <v-menu
                      v-model="endDateMenu"
                      :close-on-content-click="false"
                      transition="scale-transition"
                      offset-y
                      min-width="290px"
                    >
                      <template v-slot:activator="{ on, attrs }">
                        <v-text-field
                          v-model="formData.endDate"
                          label="End Date *"
                          prepend-icon="mdi-calendar-end"
                          readonly
                          outlined
                          :rules="[rules.required, rules.endAfterStart]"
                          v-bind="attrs"
                          v-on="on"
                          :error-messages="dateErrorMessages"
                        ></v-text-field>
                      </template>
                      <v-date-picker
                        v-model="formData.endDate"
                        :min="formData.startDate || minStartDate"
                        @input="onEndDateSelected"
                      ></v-date-picker>
                    </v-menu>
                  </v-col>

                  <!-- Duration Calculation Status -->
                  <v-col cols="12">
                    <v-alert
                      v-if="isCalculatingDays"
                      type="info"
                      dense
                      outlined
                    >
                      <v-row align="center">
                        <v-col cols="auto">
                          <v-progress-circular
                            indeterminate
                            color="indigo"
                            size="20"
                            width="2"
                          ></v-progress-circular>
                        </v-col>
                        <v-col>
                          <span class="caption">Calculating leave days...</span>
                        </v-col>
                      </v-row>
                    </v-alert>

                    <v-alert
                      v-else-if="calculatedDays > 0"
                      :type="isWithinBalance ? 'success' : 'error'"
                      dense
                      outlined
                    >
                      <v-row align="center">
                        <v-col cols="auto">
                          <v-icon
                            :color="isWithinBalance ? 'success' : 'error'"
                          >
                            {{
                              isWithinBalance
                                ? "mdi-check-circle"
                                : "mdi-alert-circle"
                            }}
                          </v-icon>
                        </v-col>
                        <v-col>
                          <div class="font-weight-bold">
                            {{ calculatedDays }} working day{{
                              calculatedDays > 1 ? "s" : ""
                            }}
                          </div>
                          <div class="caption">
                            {{ formatDate(formData.startDate) }} -
                            {{ formatDate(formData.endDate) }}
                            <span v-if="!isWithinBalance" class="red--text">
                              (Exceeds balance by
                              {{
                                (
                                  calculatedDays - leaveType.details.balance
                                ).toFixed(1)
                              }}
                              days)
                            </span>
                            <span v-else class="green--text">
                              ({{
                                (
                                  leaveType.details.balance - calculatedDays
                                ).toFixed(1)
                              }}
                              days will remain after approval)
                            </span>
                          </div>
                        </v-col>
                      </v-row>
                    </v-alert>
                  </v-col>

                  <!-- Relief Officer -->
                  <v-col cols="12">
                    <v-text-field
                      v-if="!formData.actingSupervisor.id"
                      label="Staff Acting your Position *"
                      outlined
                      readonly
                      @click="actingSupervisorDialogOpen = true"
                      :rules="[rules.required]"
                    >
                      <template v-slot:prepend>
                        <v-icon>mdi-account-search</v-icon>
                      </template>
                    </v-text-field>
                    <v-card v-else outlined class="pa-3">
                      <v-row dense align="center">
                        <v-col cols="auto">
                          <v-avatar color="primary" size="36">
                            <v-icon dark>mdi-account</v-icon>
                          </v-avatar>
                        </v-col>
                        <v-col>
                          <div class="font-weight-medium">
                            {{ formData.actingSupervisor.name }}
                          </div>
                          <div class="caption grey--text">
                            {{ formData.actingSupervisor.position || "Staff" }}
                          </div>
                        </v-col>
                        <v-spacer></v-spacer>
                        <v-col cols="auto">
                          <v-btn icon @click.stop="clearReliefOfficer">
                            <v-icon>mdi-close</v-icon>
                          </v-btn>
                        </v-col>
                      </v-row>
                    </v-card>
                  </v-col>
                  <!-- Supporting Document -->
                  <v-col cols="12">
                    <fhir-attachment
                      field="value[x]:valueAttachment"
                      :slotProps="{
                        source: {
                          fromArray: true,
                          path: 'supporting-document',
                          data: formData.supportingDoc,
                        },
                      }"
                      :edit="true"
                      path="Basic.extension[4]"
                      displayCondition=""
                      id="Basic.extension:supporting-document.value[x]:valueAttachment"
                      definition="http://ihris.org/fhir/StructureDefinition/leave-request-profile#Basic.extension:supporting-document.value[x]:valueAttachment"
                      maxValueAttachment="10MB"
                      label="Supporting Document"
                      min="1"
                      max="1"
                      attachment-types=".pdf,.jpg,.jpeg,.png"
                      :key="incrementLeave"
                    ></fhir-attachment>
                  </v-col>

                  <!-- Additional Comments -->
                  <v-col cols="12">
                    <v-textarea
                      v-model="formData.comments"
                      label="Additional Notes/Comments"
                      outlined
                      rows="2"
                      counter="300"
                      maxlength="300"
                    >
                      <template v-slot:prepend>
                        <v-icon>mdi-comment-text</v-icon>
                      </template>
                    </v-textarea>
                  </v-col>
                </v-row>
              </v-form>
            </v-card-text>
          </v-card>

          <!-- Approval Flow -->
          <v-card outlined class="mb-4">
            <v-card-text>
              <div class="text-subtitle-2 font-weight-bold mb-2">
                <v-icon small class="mr-1">mdi-information</v-icon>
                Approval Flow
              </div>
              <v-stepper flat non-linear>
                <v-stepper-header>
                  <v-stepper-step step="1" complete>Staff</v-stepper-step>
                  <v-divider></v-divider>
                  <v-stepper-step step="2">Supervisor</v-stepper-step>
                  <v-divider></v-divider>
                  <v-stepper-step step="3">HOD</v-stepper-step>
                  <v-divider></v-divider>
                  <v-stepper-step step="4">HR</v-stepper-step>
                </v-stepper-header>
              </v-stepper>
            </v-card-text>
          </v-card>

          <!-- Actions -->
          <v-card-actions class="px-0 pt-2">
            <v-btn outlined color="grey" @click="$emit('cancel')">
              <v-icon left>mdi-close</v-icon>
              Cancel
            </v-btn>
            <v-spacer></v-spacer>
            <v-btn
              color="green"
              dark
              :disabled="!canSubmit"
              :loading="submitting || isCalculatingDays"
              @click="confirmSubmit"
            >
              <v-icon left>mdi-send</v-icon>
              {{ editMode ? "Update" : "Submit" }} Maternity Leave Request
            </v-btn>
          </v-card-actions>
        </v-col>
      </v-row>

      <!-- Staff Selection Dialog -->
      <staff-selection-dialog
        v-model="actingSupervisorDialogOpen"
        title="Select Acting Supervisor"
        :exclude-ids="excludedStaffIds"
        @selected="actingSupervisorSelected"
      />
    </v-card-text>
  </v-card>
</template>

<script>
import StaffSelectionDialog from "./staff-selection-dialog.vue";
import processQuestionnaire from "../../mixins/processQuestionnaire";

export default {
  name: "MaternityLeaveRequest",
  mixins: [processQuestionnaire],
  props: {
    leaveType: {
      type: Object,
      required: true,
    },
    leaveInfo: {
      type: Object,
      required: true,
    },
    practitioner: {
      type: String,
      required: true,
    },
    requestId: {
      type: String,
      default: null,
    },
  },

  data() {
    return {
      url: "http://ihris.org/fhir/Questionnaire/leave-request",
      fhir: {},
      fhirId: "",
      profile:
        "http://ihris.org/fhir/StructureDefinition/leave-request-profile",
      confirmDialog: false,
      overlay: false,
      valid: false,
      submitting: false,
      editMode: false,

      startDateMenu: false,
      endDateMenu: false,

      isCalculatingDays: false,
      calculatedDays: 0,
      calculationError: null,

      actingSupervisorDialogOpen: false,
      loadingDoctorStatus: false, // Kept for consistency with parent component

      formData: {
        actingSupervisor: {},
        startDate: "",
        endDate: "",
        supportingDoc: {},
        comments: "",
      },
      incrementLeave: 0,

      rules: {
        required: (value) => {
          if (value === undefined || value === null || value === "") {
            return "This field is required";
          }
          if (typeof value === "object" && !value.id) {
            return "This field is required";
          }
          return true;
        },
        minLength: (min) => (value) =>
          !value || value.length >= min || `Minimum ${min} characters required`,
        phone: (value) => {
          if (!value) return true;
          return /^[0-9+\-\s()]+$/.test(value) || "Invalid phone number";
        },
        endAfterStart: (value) => {
          if (!value || !this.formData.startDate) return true;
          return (
            new Date(value) >= new Date(this.formData.startDate) ||
            "End date must be after start date"
          );
        },
      },
    };
  },

  computed: {
    excludedStaffIds() {
      return [this.practitioner];
    },

    minStartDate() {
      const today = new Date();
      return today.toISOString().substr(0, 10);
    },

    isWithinBalance() {
      return this.calculatedDays <= this.leaveType.details.balance;
    },

    canSubmit() {
      return (
        this.valid &&
        !this.isCalculatingDays &&
        this.calculatedDays > 0 &&
        this.isWithinBalance &&
        this.formData.actingSupervisor?.id &&
        !this.submitting
      );
    },

    dateErrorMessages() {
      if (this.calculationError) {
        return [this.calculationError];
      }
      if (this.calculatedDays > 0 && !this.isWithinBalance) {
        return [
          `Insufficient leave balance (Available: ${this.leaveType.details.balance} days)`,
        ];
      }
      return [];
    },
  },

  watch: {
    requestId: {
      immediate: true,
      async handler(id) {
        if (id) {
          await this.loadEditingData(id);
        }
      },
    },
  },

  methods: {
    async calculateLeaveDays() {
      if (!this.formData.startDate || !this.formData.endDate) {
        this.calculatedDays = 0;
        this.calculationError = null;
        return;
      }

      this.isCalculatingDays = true;
      this.calculationError = null;
      this.calculatedDays =
        this.$moment(this.formData.endDate).diff(
          this.formData.startDate,
          "days",
        ) + 1;
      this.isCalculatingDays = false;
    },

    async onStartDateSelected() {
      this.startDateMenu = false;
      this.formData.endDate = "";
      this.calculatedDays = 0;
      this.calculationError = null;
      await this.calculateLeaveDays();
    },

    async onEndDateSelected() {
      this.endDateMenu = false;
      await this.calculateLeaveDays();
    },

    actingSupervisorSelected(staff) {
      this.formData.actingSupervisor = staff;
    },

    clearReliefOfficer() {
      this.formData.actingSupervisor = {};
    },

    formatDate(dateString) {
      if (!dateString) return "N/A";
      const date = new Date(dateString);
      return date.toLocaleDateString("en-US", {
        year: "numeric",
        month: "short",
        day: "numeric",
      });
    },

    getProgressColor(balance, total) {
      const percentage = (balance / total) * 100;
      if (percentage > 50) return "green";
      if (percentage > 25) return "orange";
      return "red";
    },

    resetForm() {
      this.formData = {
        actingSupervisor: {},
        startDate: "",
        endDate: "",
        supportingDoc: {},
        comments: "",
      };
      this.calculatedDays = 0;
      this.calculationError = null;
    },

    getExtValue(resource, urlPart, valueType) {
      const ext = resource.extension?.find((ext) => ext.url.includes(urlPart));
      return ext ? ext[valueType] : null;
    },

    async loadEditingData(id) {
      this.editMode = true;
      this.fhirId = id;

      try {
        const url = `/fhir/Basic?_id=${id}&_revinclude=Basic:leaverequest`;
        const response = await fetch(url);
        const resources = await response.json();

        const leaveRequest = resources.entry.find(
          (entry) => entry.resource.id === id,
        )?.resource;

        // Extract form data
        this.formData.startDate = this.getExtValue(
          leaveRequest,
          "start-date",
          "valueDate",
        );
        this.formData.endDate = this.getExtValue(
          leaveRequest,
          "end-date",
          "valueDate",
        );
        this.formData.comments = this.getExtValue(
          leaveRequest,
          "comments",
          "valueString",
        );

        // Extract acting supervisor
        const actingSupExt = leaveRequest.extension?.find(
          (ext) =>
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/acting-supervisor",
        );
        if (actingSupExt?.valueReference?.reference) {
          const actingId = actingSupExt.valueReference.reference.split("/")[1];
          try {
            const actingResponse = await fetch(
              `/fhir/Practitioner/${actingId}`,
            );
            const actingPractitioner = await actingResponse.json();
            const name = actingPractitioner.name?.[0];
            this.formData.actingSupervisor = {
              id: actingId,
              name: name
                ? `${name.given?.join(" ")} ${name.family}`.trim()
                : "Unknown",
            };
          } catch (err) {
            console.error("Error loading acting supervisor:", err);
          }
        }

        // Extract supporting document
        const docExt = leaveRequest.extension?.find(
          (ext) =>
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/supporting-document",
        );
        if (docExt?.valueAttachment) {
          this.formData.supportingDoc = docExt.valueAttachment;
        }

        // Calculate days
        if (this.formData.startDate && this.formData.endDate) {
          await this.calculateLeaveDays();
        }
        this.incrementLeave++;
      } catch (error) {
        console.error("Error loading editing data:", error);
        this.showSnackbar("Error loading leave request data", "error");
      }
    },

    confirmSubmit() {
      this.$refs.form.validate();
      if (!this.valid) {
        this.showSnackbar("Please complete all required fields", "warning");
        return;
      }
      this.confirmDialog = true;
    },

    async submitRequest() {
      if (!this.$refs.form.validate()) {
        return;
      }
      this.confirmDialog = false;
      this.submitting = true;
      this.overlay = true;

      try {
        this.fhir = {
          leaveCategory: "maternity-leave",
          requestDate: new Date().toISOString().split("T")[0],
          startDate: this.formData.startDate,
          endDate: this.formData.endDate,
          days: this.calculatedDays.toString(),
          comments: this.formData.comments,
          actingSupervisor: this.formData.actingSupervisor?.id,
        };

        await this.processFHIR();

        this.showSnackbar(
          this.editMode
            ? "Maternity leave request updated successfully!"
            : "Maternity leave request submitted successfully!",
          "success",
        );

        // Reset form
        this.resetForm();
        this.overlay = false;
        this.submitting = false;
        this.editMode = false;
        this.fhirId = "";
        this.$emit("submit");
      } catch (error) {
        console.error("Error submitting maternity leave request:", error);
        this.showSnackbar(
          error.message || "Error submitting maternity leave request",
          "error",
        );
        this.overlay = false;
        this.submitting = false;
      } finally {
        this.submitting = false;
      }
    },

    showSnackbar(message, color) {
      this.$emit("snackbar", { message, color });
    },
  },

  components: {
    StaffSelectionDialog,
    "fhir-attachment": () => import("@/components/fhir/fhir-attachment"),
  },
};
</script>

